266	// ── Main ──────────────────────────────────────────────────────────────────────
267	
268	async function main(): Promise<void> {
269	  // ── Read formal ABI env vars ────────────────────────────────────────────────
270	  let taskId: string;
271	  let featureId: string;
272	  let taskRepoUrl: string;
273	  let taskRepoBranch: string;
274	  let executorWorkdir: string;
275	  let mgmtRepoUrl: string;
276	  let briefingPath: string;
277	  let resultPath: string;
278	  let sshKeyPath: string | undefined;
279	  let githubToken: string;
280	
281	  try {
282	    taskId = requireEnv("TASK_ID");
283	    featureId = requireEnv("FEATURE_ID");
284	    taskRepoUrl = requireEnv("TASK_REPO_URL");
285	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
286	    executorWorkdir = requireEnv("EXECUTOR_WORKDIR");
287	    mgmtRepoUrl = requireEnv("MGMT_REPO_URL");
288	    briefingPath = requireEnv("BRIEFING_PATH");
289	    resultPath = requireEnv("RESULT_PATH");
290	    githubToken = process.env.GITHUB_TOKEN ?? "";
291	    sshKeyPath = resolveSSHKey({ SSH_PRIVATE_KEY: process.env.SSH_PRIVATE_KEY }).sshKeyPath;
292	  } catch (e) {
293	    emit({ type: "executor_fatal", details: (e as Error).message });
294	    process.exit(1);
295	  }
296	
297	  const budgetTokensStr = process.env.BUDGET_TOKENS;
298	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
299	
300	  const implDir = join(executorWorkdir, "impl");
301	  const mgmtDir = join(executorWorkdir, "mgmt");
302	
303	  // Day-1 single-container extras.
304	  const workspaceRoot = mgmtDir;
305	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
306	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
307	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
308	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
309	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
310	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
311	  const mcpRagUrl = process.env.MCP_RAG_URL;
312	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
313	  const gitnexusMcpUrl = process.env.GITNEXUS_MCP_URL;
314	  const implementationModel = process.env.IMPLEMENTATION_MODEL;
315	  const executorKind = (process.env.EXECUTOR_KIND ?? "impl") as "impl" | "review";
316	  const implPrUrl = process.env.IMPL_PR_URL ?? "";
317	
318	  const runStartIso = new Date().toISOString();
319	
320	  // ── 1. Two-phase repo materialization ─────────────────────────────────────
321	  // Phase 1: management repo (read-only — workspace rules, briefing, skills)
322	  try {
323	    materializeMgmtRepo(mgmtRepoUrl, mgmtDir, sshKeyPath);
324	    process.env.WORKSPACE_ROOT = mgmtDir;
325	  } catch (e) {
326	    const details = `mgmt repo materialization failed: ${String(e)}`;
327	    emit({ type: "executor_fatal", task_id: taskId, details });
328	    writeResult(resultPath, {
329	      terminal_status: "failed",
330	      blocked_reason: `mgmt_repo_materialization_failed: ${String(e)}`,
331	    });
332	    process.exit(0);
333	  }
334	
335	  // Phase 2: implementation repo
336	  const taskRepoBaseBranch = process.env.TASK_REPO_BASE_BRANCH ?? "";
337	  try {
338	    materializeRepo(taskRepoUrl, taskRepoBranch, implDir, sshKeyPath);
339	    process.env.TASK_REPO_PATH = implDir;
340	  } catch (e) {
341	    const details = `impl repo materialization failed: ${String(e)}`;
342	    emit({ type: "executor_fatal", task_id: taskId, details });
343	    writeResult(resultPath, {
344	      terminal_status: "failed",
345	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
346	    });
347	    process.exit(0);
348	  }
349	
350	  // Ensure `feature/{featureId}` exists on the impl repo remote so PR creation
351	  // can target it. Uses TASK_REPO_BASE_BRANCH (the repo's root base branch, e.g.
352	  // "main") as the push source — not TASK_BASE_BRANCH, which is the feature branch
353	  // itself and cannot be used as its own creation source.
354	  if (taskRepoBaseBranch) {
355	    ensureImplFeatureBranch(featureId, taskRepoBaseBranch, implDir, sshKeyPath, emit);
356	  }
357	
358	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
359	  const missingTools = checkRequiredTools(implDir);
360	  if (missingTools.length > 0) {
